fn describe_later(c: bool) -> i32 {
  let h = if c { None } else { At { index: 1 } };   // OK: else 側で Hit に決まる
  match h { None => 0, At { index } => index }
}

fn bad() -> i32 {
  let h = None;
  match h { None => 0, _ => 1 }
  // error: cannot tell which enum `None` is before matching on it: write `Hit::None`
}

fn grow(c: Shape::Circle) -> Shape::Circle { Circle { ...c, r: c.r * 2.0 } }

pub fn area(s: Shape) -> f64 {
  match s {
    c @ Circle { .. } => 3.141592653589793 * grow(c).r,
    Rect { .. } | Label { .. } => 0.0,
  }
}
